create table if not exists public.membership_role_audit (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null,
  user_id uuid not null,
  old_role text,
  new_role text not null,
  changed_at timestamptz not null default now(),
  changed_by uuid null
);

create index if not exists membership_role_audit_org_id_idx on public.membership_role_audit(org_id);
create index if not exists membership_role_audit_user_id_idx on public.membership_role_audit(user_id);
create index if not exists membership_role_audit_changed_at_idx on public.membership_role_audit(changed_at);

