create table if not exists public.invoice_status_audit (
  id uuid primary key default gen_random_uuid(),
  invoice_id uuid not null,
  org_id uuid not null,
  action text not null check (action in ('insert','status_update')),
  old_status text null,
  new_status text null,
  changed_at timestamptz not null default now()
);

create index if not exists invoice_status_audit_invoice_id_idx on public.invoice_status_audit(invoice_id);
create index if not exists invoice_status_audit_org_id_idx on public.invoice_status_audit(org_id);

create or replace function public.log_invoice_status_change()
returns trigger
language plpgsql
as $$
begin
  if (tg_op = 'INSERT') then
    insert into public.invoice_status_audit(invoice_id, org_id, action, old_status, new_status)
    values (new.id, new.org_id, 'insert', null, new.status);
    return new;
  elsif (tg_op = 'UPDATE') then
    if (new.status is distinct from old.status) then
      insert into public.invoice_status_audit(invoice_id, org_id, action, old_status, new_status)
      values (new.id, new.org_id, 'status_update', old.status, new.status);
    end if;
    return new;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_invoice_status_audit on public.invoices;
create trigger trg_invoice_status_audit
after insert or update on public.invoices
for each row execute function public.log_invoice_status_change();
